(() => {
  const xml = document.documentElement;
  const items = Array.from(xml.querySelectorAll('item')).slice(0, 15).map((item, i) => {
    const get = sel => item.querySelector(sel)?.textContent?.trim() || '';
    const title = get('title');
    const link = get('link');
    const pubDate = get('pubDate');
    const creator = get('dc\\:creator, creator');
    const cats = Array.from(item.querySelectorAll('category')).map(c=>c.textContent.trim());
    const content = get('content\\:encoded, encoded');
    const desc = get('description');
    const text = (content || desc).replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
    const minRead = ((content || desc).match(/\b\d+\s+min\s+read\b/i)||[])[0] || '';
    return {i, title, link, creator, pubDate, categories: cats.slice(0,8), minRead, snippet: text.slice(0,500)};
  });
  return {url: location.href, count: xml.querySelectorAll('item').length, items};
})()

(() => {
